const path = require("path");
const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  const base = path.dirname(require.resolve("tailwindcss/package.json"));
  const ds = await tw.__unstable__loadDesignSystem('@import "tailwindcss";', {
    base,
    loadStylesheet: async (id, b) => {
      const file = id === "tailwindcss" ? path.join(base, "index.css") : path.resolve(b, id);
      return { path: file, base: path.dirname(file), content: fs.readFileSync(file, "utf8") };
    },
  });
  if (typeof ds.canonicalizeCandidates !== "function") broken("canonicalizeCandidates is missing");
  const out = ds.canonicalizeCandidates(["px-[1.2rem]", "py-[1.2rem]", "text-left"], { collapse: true, logicalToPhysical: true, rem: 16 });
  if (!Array.isArray(out)) broken("canonicalizeCandidates returned " + typeof out);
  const s = JSON.stringify(out.slice().sort());
  if (s === JSON.stringify(["p-[1.2rem]", "text-left"])) { console.log("OK: px-[1.2rem] py-[1.2rem] collapse to p-[1.2rem]"); return; }
  if (s === JSON.stringify(["px-[1.2rem]", "py-[1.2rem]", "text-left"])) symptom("canonicalizeCandidates does not collapse px-[1.2rem] py-[1.2rem] into p-[1.2rem]");
  broken("unexpected output " + JSON.stringify(out));
})().catch(e => broken(String(e && e.stack || e)));

